  sources: [['CMS: Hospital Equipment Maintenance Requirements (S&C 14-07)', 'https://www.cms.gov/medicare/provider-enrollment-and-certification/surveycertificationgeninfo/downloads/survey-and-cert-letter-14-07.pdf'], ['NIST: Metrological Traceability', 'https://www.nist.gov/calibrations/traceability'], ['AAMI: Healthcare Technology Management', 'https://www.aami.org/htm'], ['The Joint Commission: Environment of Care', 'https://www.jointcommission.org/resources/patient-safety-topics/environment-of-care/']],
